/* Small motion polish; keep home mounted so hidden can transition. */
.home { opacity: 1; transform: translateY(0); visibility: visible; transition: opacity .24s ease, transform .24s ease, visibility 0s; }
.home.hidden { display: flex; opacity: 0; transform: translateY(14px); visibility: hidden; pointer-events: none; transition-delay: 0s, 0s, .24s; }

.modal .card { animation: none; }
:is(#modal, #lsel, #settings, #shop):not(.hidden) > .card { animation: toyPop .36s ease-out; }
@keyframes toyPop {
  0% { opacity: 0; transform: translateY(10px) scale(.88); }
  65% { opacity: 1; transform: translateY(-2px) scale(1.035); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

.homeplay { animation: homeBob 2.4s ease-in-out infinite; }
@keyframes homeBob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }
button:active:not(:disabled) { animation: none !important; transform: translateY(3px) scale(1.03, .92) !important; }
.nav button.on:active:not(:disabled) { transform: translateY(-3px) scale(1.03, .92) !important; }
.nav button:active i { animation: navWiggle .28s ease-in-out; }
@keyframes navWiggle { 0%, 100% { transform: rotate(0); } 30% { transform: rotate(-12deg); } 70% { transform: rotate(10deg); } }

#lsel:not(.hidden) .lv { animation: toyPop .3s ease-out backwards; animation-delay: calc(min(var(--i, 0), 12) * 25ms); }

.pill { position: relative; }
.pill::after { content: ''; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; background: linear-gradient(110deg, transparent 42%, rgba(255,255,255,.45) 50%, transparent 58%) 160% 0 / 250% 100% no-repeat; animation: coinShine 4.8s ease-in-out infinite; }
@keyframes coinShine { 0%, 78% { background-position: 160% 0; } 100% { background-position: -160% 0; } }

@media (prefers-reduced-motion: reduce) {
  .shell, .shell *, .shell *::before, .shell *::after { animation: none !important; transition: none !important; }
  .home.hidden { transform: none; }
  .pill::after { content: none; }
}
</style>
